// Splits AGENTS.md sections into path-scoped .claude/rules/*.md files Claude Code loads only
// while editing a matching source file, instead of on every session regardless of what is being
// edited (AGENTS.md 3, P0-18/P0-19). AGENTS.md stays the only hand-edited source; `--check`
// verifies every generated file still matches it, wired into `lint:generated` the same way
// `npm pack --dry-run` backs `pack:check`.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { format, resolveConfig } from 'prettier';

const repoRoot = join(import.meta.dirname, '..');
const agentsPath = join(repoRoot, 'AGENTS.md');
const rulesDir = join(repoRoot, '.claude', 'rules');

const RULES = [
  {
    outFile: 'typescript-code-style.md',
    sectionStart: '## 5. TypeScript code style',
    sectionEnd: '## 8. Branches, commits and pull requests',
    sourceNote: 'AGENTS.md sections 5-7',
    paths: ['packages/**/*.ts', 'examples/**/*.ts', 'scripts/**/*.mjs', 'scripts/**/*.cjs'],
  },
  {
    outFile: 'testing.md',
    sectionStart: '## 13. Testing',
    sectionEnd: '## 14. Security',
    sourceNote: 'AGENTS.md section 13',
    // Narrower than typescript-code-style.md's `**/*.ts`: testing conventions only apply while
    // editing a test file itself, not every source file the tests exercise.
    paths: [
      'packages/**/*.test.ts',
      'packages/**/test/**/*.ts',
      'examples/**/*.test.ts',
      'examples/**/test/**/*.ts',
    ],
  },
];

function extractSection(agentsSource, rule) {
  const startIndex = agentsSource.indexOf(rule.sectionStart);
  const endIndex = agentsSource.indexOf(rule.sectionEnd);
  if (startIndex === -1 || endIndex === -1 || endIndex <= startIndex) {
    throw new Error(
      `Could not find ${rule.sourceNote} between "${rule.sectionStart}" and "${rule.sectionEnd}".`,
    );
  }
  return agentsSource.slice(startIndex, endIndex).trimEnd();
}

// Renders the exact bytes this repository's own `npm run lint` (prettier --check) expects, so a
// generated file never fails formatting on its own — including YAML frontmatter's line-wrapping,
// which is not worth reimplementing by hand here.
async function render(rule, section, outPath) {
  const pathsYaml = `[${rule.paths.map((path) => `'${path}'`).join(', ')}]`;
  const draft = [
    '---',
    `paths: ${pathsYaml}`,
    '---',
    '',
    `<!-- Generated by scripts/generate-claude-rules.mjs from ${rule.sourceNote}. -->`,
    '<!-- Do not edit by hand: edit AGENTS.md and run "npm run generate". -->',
    '',
    section,
    '',
  ].join('\n');
  const config = await resolveConfig(outPath);
  return format(draft, { ...config, filepath: outPath });
}

function readExisting(outPath) {
  try {
    return readFileSync(outPath, 'utf8');
  } catch (error) {
    if (error instanceof Error && 'code' in error && error.code === 'ENOENT') {
      return undefined;
    }
    throw error;
  }
}

const agentsSource = readFileSync(agentsPath, 'utf8');
const checkOnly = process.argv.includes('--check');
let outOfDate = false;

for (const rule of RULES) {
  const outPath = join(rulesDir, rule.outFile);
  const rendered = await render(rule, extractSection(agentsSource, rule), outPath);

  if (checkOnly) {
    if (readExisting(outPath) !== rendered) {
      console.error(`${outPath} does not match AGENTS.md. Run "npm run generate" and commit the result.`);
      outOfDate = true;
    } else {
      console.log(`${outPath} is up to date.`);
    }
    continue;
  }

  mkdirSync(rulesDir, { recursive: true });
  writeFileSync(outPath, rendered);
  console.log(`Generated ${outPath}`);
}

if (checkOnly && outOfDate) {
  process.exit(1);
}
